{
  "title": "Cusco, With a Twist",
  "summary": "A day that mixes the crew's must-see history with a quiet, unexpected stop among the terraces of Moray.",
  "stops": [
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The old stones of Qorikancha still hold their secrets, and it is the right way to start a day of surprises.",
      "poi_id": "p2"
    },
    {
      "poi_id": "p5",
      "kind": "activity",
      "must_do_id": null,
      "note": "A short visit to the cathedral, because its paintings hide stories most visitors walk right past.",
      "poi_id": "p5"
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "A proper lunch with good vegetarian plates, and a chance to rest the legs before the long ride.",
      "poi_id": "p19"
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": "m3",
      "note": "Pisac stays, of course. The hike up there is the kind of tired you thank me for later.",
      "poi_id": "p9"
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Moray is the surprise: giant green rings in the earth that feel like a secret the mountains kept for us.",
      "poi_id": "p11"
    }
  ]
}

